button { padding: 10px 16px; border: 0; border-radius: 6px; color: white; background: #245fc3; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #174b9e; }
button:focus-visible, input:focus-visible { outline: 3px solid #91b6f2; outline-offset: 2px; }
#alert { color: #b42318; }
.project-list { display: grid; gap: 10px; margin-top: 24px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 16px; border: 1px solid #e1e6ed; border-radius: 8px; }
@media (max-width: 600px) { .container { margin: 16px; padding: 22px; } .form-row { align-items: stretch; flex-direction: column; } }
